function parseAmount(input) {
  const text = String(input).trim();
  if (!/^\d+(\.\d{1,2})?$/.test(text)) throw new Error(`Not a valid amount: "${input}"`);
  const [whole, fraction = ''] = text.split('.');
  const cents = Number(whole) * 100 + Number(fraction.padEnd(2, '0'));
  if (cents === 0) throw new Error('Amount must be greater than zero');
  return cents;
}

// Mounts the "Add expense" form into container.
// - Text fields labelled "Description" and "Amount", and an
//   "Add expense" button.
// - On click, if valid: calls onAdd({ description, amountCents }) with the
//   trimmed description and the amount in integer cents, hides any error,
//   then clears both fields.
// - If invalid: shows the reason in the element with role="alert",
//   does NOT call onAdd, and keeps what the user typed.
//   Blank description -> "Add a description"; bad amount -> parseAmount's message.
// (The playground blocks real form submission, so this reacts to the click.)
function mountExpenseForm(container, onAdd) {
  container.innerHTML = `
    <div>
      <label>Description <input name="description"></label>
      <label>Amount <input name="amount" inputmode="decimal"></label>
      <button type="button">Add expense</button>
      <p role="alert" hidden></p>
    </div>`;
  const [description, amount] = container.querySelectorAll('input');
  const alert = container.querySelector('[role="alert"]');
  container.querySelector('button').addEventListener('click', () => {
    let amountCents;
    try {
      if (!description.value.trim()) throw new Error('Add a description');
      amountCents = parseAmount(amount.value);
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
      return;
    }
    alert.hidden = true;
    alert.textContent = '';
    onAdd({ description: description.value.trim(), amountCents });
    description.value = '';
    amount.value = '';
  });
}

